# hae/evaluation/artifacts.py
"""Canonical definition of what counts as a produced artifact."""

import os
from pathlib import Path
from typing import Dict, Iterable, Tuple

EXCLUDED_DIR_SEGMENTS = (
    '.pytest_cache', '__pycache__', 'venv', '.venv', '.git', '.mypy_cache',
    '.ruff_cache', '.tox', 'node_modules', '.ipynb_checkpoints'
)
EXCLUDED_DIR_SUFFIXES = ('.egg-info', '.dist-info')


def is_generated_path(path: str) -> bool:
    """True if the path lives inside a machine-generated directory."""
    p = Path(path)
    parts = p.parts
    for part in parts:
        if part in EXCLUDED_DIR_SEGMENTS:
            return True
        for suffix in EXCLUDED_DIR_SUFFIXES:
            if part.endswith(suffix):
                return True
    return False


def _sanitize_component(component: str) -> str:
    """Helper to sanitize a single path component (filename or directory name)."""
    temp_component = component.strip()
    if not temp_component:
        return ""

    while True:
        last_component = temp_component

        # Symmetrical stripping: longer markers first
        if len(temp_component) > 4 and temp_component.startswith('**') and temp_component.endswith('**'):
            temp_component = temp_component[2:-2]
        elif len(temp_component) > 4 and temp_component.startswith('__') and temp_component.endswith('__'):
            temp_component = temp_component[2:-2]
        elif len(temp_component) > 2 and temp_component.startswith('*') and temp_component.endswith('*'):
            temp_component = temp_component[1:-1]
        elif len(temp_component) > 2 and temp_component.startswith('_') and temp_component.endswith('_'):
            temp_component = temp_component[1:-1]
        elif len(temp_component) > 2 and temp_component.startswith('`') and temp_component.endswith('`'):
            temp_component = temp_component[1:-1]
        # Asymmetrical stripping: specifically for trailing `**` like `routing.py**`
        # This is applied iteratively with symmetrical stripping.
        # Example: `**file.py**` -> `file.py**` (symmetric) -> `file.py` (asymmetric)
        # Example: `file.py**` -> `file.py` (asymmetric)
        elif temp_component.endswith('**'):
            temp_component = temp_component[:-2]

        if temp_component == last_component:
            break
    return temp_component.strip()


def sanitize_path(path: str) -> str:
    """Strips markdown decoration from an agent-supplied path.

    This function now sanitizes each component of the path, addressing cases
    where markdown might appear in directory names as well as filenames.
    Applied at write time so the artifact lands at its intended location rather
    than being silently created with a broken name.
    """
    original_path = path.strip()
    if not original_path:
        return ""

    p = Path(original_path)
    parts = p.parts
    sanitized_parts = []

    # Path.parts correctly handles root components (e.g., '/', 'C:\') by including
    # them as the first part. _sanitize_component is designed to be safe for
    # these special parts (e.g., '/' remains '/', 'C:\' remains 'C:\').
    for part in parts:
        sanitized_part = _sanitize_component(part)
        if sanitized_part:  # Only add non-empty parts
            sanitized_parts.append(sanitized_part)

    if not sanitized_parts:
        return ""

    # Reconstruct the path. os.path.join handles leading slashes, drive letters,
    # and normalizes multiple slashes. It also removes trailing slashes unless
    # the path is just a root (e.g., '/', 'C:\'), which is desirable for file paths.
    reconstructed_path = os.path.join(*sanitized_parts)

    return reconstructed_path


def is_malformed_path(path: str) -> bool:
    """True if markdown formatting or stray whitespace leaked into the filename.

    Agents emit paths through a ReAct text protocol, so bold markers and
    backticks periodically survive into `write_file` calls. The resulting files
    are unusable -- `routing.py**` is not importable -- but they were previously
    counted as delivered artifacts, and often duplicated a correctly named file.
    """
    return path != sanitize_path(path)


def filter_bundle(bundle: Dict[str, str]) -> Dict[str, str]:
    """Returns only genuinely agent-authored files from a path->content map."""
    authored_files = {}
    for path, content in bundle.items():
        if not is_generated_path(path) and not is_malformed_path(path):
            authored_files[path] = content
    return authored_files


def partition_bundle(bundle: Dict[str, str]) -> Tuple[Dict[str, str], Dict[str, str], Dict[str, str]]:
    """Splits a bundle into (authored, generated, malformed) for reporting."""
    authored: Dict[str, str] = {}
    generated: Dict[str, str] = {}
    malformed: Dict[str, str] = {}

    for path, content in bundle.items():
        if is_generated_path(path):
            generated[path] = content
        elif is_malformed_path(path):
            malformed[path] = content
        else:
            authored[path] = content

    return authored, generated, malformed


def count_source_files(bundle: Dict[str, str], suffixes: Iterable[str] = ('.py',)) -> int:
    """Counts authored files matching the given suffixes."""
    authored_files = filter_bundle(bundle)
    suffix_tuple = tuple(suffixes)
    count = 0
    for path in authored_files:
        if path.endswith(suffix_tuple):
            count += 1
    return count
